export type OnboardingDependencies={db:TenantTransactionRunner;env?:NodeJS.ProcessEnv;requestId?:string};
const uuid=z.uuid().transform(value=>value.toLowerCase()),optionsInput=z.object({sessionId:uuid.optional()}).strict(),directoryInput=z.object({cursor:z.string().max(6000).optional()}).strict(),recoverInput=z.object({idempotencyKey:uuid,sessionId:uuid.optional()}).strict(),protocol="NATIVE_PRIVATE_PROPERTY_ONBOARDING_V1";
const cursorSchema=z.object({protocol:z.literal(protocol),organizationId:uuid,actorId:uuid,filter:z.string(),asOf:z.iso.datetime(),beforeId:uuid,beforeAt:z.iso.datetime().optional()}).strict();
type Row=PropertyOnboardingRevision;
const resource=(organizationId:string,row?:Pick<Row,"sessionId"|"ownerId"|"propertyId"|"step"|"createdAt">)=>({type:"onboarding",organizationId,id:row?.sessionId,ownerId:row?.ownerId,propertyId:row?.propertyId??undefined,status:row?.step,occurredAt:row?.createdAt,dataClass:"operational"as const});
const ownerResource=(organizationId:string,owner?:{id:string;createdAt:Date})=>({type:"owner",organizationId,id:owner?.id,ownerId:owner?.id,occurredAt:owner?.createdAt,dataClass:"personal"as const});
function actorContext(actor:AccountActorContext){if(actor.organizationId!==actor.authContext.organizationId||actor.actorId!==actor.authContext.userAccountId)throw new OnboardingAccessError();return{...actor,authContext:restoreAuthorizationCap(captureAuthorizationCap(actor.authContext))};}
async function authority(actor:AccountActorContext,tx:TenantTransaction,checks:readonly CurrentAuthorityCheck[]){const stored=await authContextForAccountInTransaction(tx,actor.organizationId,actor.actorId),now=await new OnboardingRepository(tx,actor.organizationId).clock();assertAccountAuthorization(actor,stored,now,checks,new OnboardingAccessError());return{stored,now};}
async function settings(tx:TenantTransaction,organizationId:string,now:Date){const rule=await new ConfigRuleRepository(tx,organizationId).resolve({key:onboardingPolicyKey,scopes:[{scopeType:"organization",scopeId:null}],asOf:now}),parsed=onboardingPolicySchema.safeParse(rule?.parsedValue);if(!rule?.createdBy||rule.lifecycle!=="ACTIVE"||!parsed.success)throw new OnboardingConfigurationError();return{rule,policy:parsed.data,snapshot:{id:rule.id,version:rule.version,value:parsed.data}};}
function retainedPolicy(row:Row){const value=z.object({id:uuid,version:z.number().int().positive(),value:onboardingPolicySchema}).strict().parse(row.policySnapshot);if(value.id!==row.policyId||value.version!==row.policyVersion)throw new OnboardingConfigurationError();return value.value;}
async function ownerRead(actor:AccountActorContext,tx:TenantTransaction,ownerId:string,write=false,includeArchived=false){const owner=await nativeOnboardingOwnerHead(tx,actor.organizationId,ownerId,includeArchived);if(!owner)throw new OnboardingAccessError();await authority(actor,tx,[{action:"view",resource:ownerResource(actor.organizationId,owner)},...write?[{action:"edit"as const,resource:ownerResource(actor.organizationId,owner)}]:[]]);return owner;}
async function sessionContext(actor:AccountActorContext,tx:TenantTransaction,sessionId:string,action:"view"|"edit"="view",personal=false){const repository=new OnboardingRepository(tx,actor.organizationId),row=await repository.current(sessionId);if(!row)throw new OnboardingAccessError();await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId,row)},...action==="edit"?[{action,resource:resource(actor.organizationId,row)}]:[],...personal?[{action:"export"as const,resource:{...resource(actor.organizationId,row),dataClass:"personal"as const}}]:[]]);return{repository,row};}
async function spendRead(actor:AccountActorContext,deps:OnboardingDependencies,sessionId?:string){const decision=await withTenant(deps.db,actor.organizationId,async tx=>{const repository=new OnboardingRepository(tx,actor.organizationId);let row:Row|undefined;if(sessionId)row=(await sessionContext(actor,tx,sessionId)).row;else await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId),organizationOnly:true}]);const now=await repository.clock();let policy;try{policy=(await settings(tx,actor.organizationId,now)).policy;}catch(error){if(!(error instanceof OnboardingConfigurationError)||!row)throw error;policy=retainedPolicy(row);}return consumeRateLimit(tx,actor.organizationId,{key:"onboarding:reads:organization",limit:policy.reads.requests,windowSeconds:policy.reads.window_seconds,now});});if(!decision.allowed)throw new OnboardingRateLimitError(decision.resetAt);}
function binding(row:Row){return{organizationId:row.organizationId,sessionId:row.sessionId,revisionId:row.id,ownerId:row.ownerId,createdBy:row.createdBy,commandKey:row.commandKey,policyId:row.policyId,policyVersion:row.policyVersion};}
function retained(row:Row,env?:NodeJS.ProcessEnv){const value=decryptOnboardingPayload(row.encryptedPayload,binding(row),env);if(value.command.reviewFingerprint!==row.reviewFingerprint||value.command.previousRevisionId!==row.previousId||value.command.step!==row.step||value.command.target.mode!==row.mode)throw new OnboardingConfigurationError();return value;}
function receipt(row:Row,replayed=false){return onboardingReceiptSchema.parse({id:row.id,sessionId:row.sessionId,previousRevisionId:row.previousId,number:row.number,step:row.step,ownerId:row.ownerId,propertyId:row.propertyId,createdAt:row.createdAt.toISOString(),replayed});}
function sourceSnapshot(owner:NonNullable<Awaited<ReturnType<typeof nativeOnboardingOwnerWitness>>>){return{source:"CORE_OWNER_IDENTITY",ownerId:owner.id,ownerXmin:owner.xmin,ownerTuple:owner.tuple,ownerCreatedAt:owner.createdAt.toISOString(),ownerUpdatedAt:owner.updatedAt.toISOString()};}
async function draftContext(actor:AccountActorContext,tx:TenantTransaction,draft:OnboardingDraft){
 const repository=new OnboardingRepository(tx,actor.organizationId),current=draft.sessionId?(await sessionContext(actor,tx,draft.sessionId,"edit",true)).row:null;
 if(current&&(current.id!==draft.previousRevisionId||current.step!=="OWNER"||current.propertyId!==null))throw new OnboardingConflictError();
 if(!current)await authority(actor,tx,(["view","create","export"]as const).map(action=>({action,resource:resource(actor.organizationId),organizationOnly:true})));
 const configured=await settings(tx,actor.organizationId,await repository.clock());if(!configured.policy.owner_modes.includes(draft.target.mode))throw new OnboardingConfigurationError();
 let owner,source;
 if(draft.target.mode==="LINK"){
  await ownerRead(actor,tx,draft.target.ownerId,true);const before=await nativeOnboardingOwnerWitness(tx,actor.organizationId,draft.target.ownerId),identity=await nativeOnboardingOwnerIdentity(tx,actor.organizationId,draft.target.ownerId),after=await nativeOnboardingOwnerWitness(tx,actor.organizationId,draft.target.ownerId);if(!before||!identity||!after||commandFingerprint(sourceSnapshot(before))!==commandFingerprint(sourceSnapshot(after)))throw new OnboardingConflictError();owner=nativeOwnerIdentityProjection(identity);source=sourceSnapshot(after);
 }else{await authority(actor,tx,[{action:"create",resource:ownerResource(actor.organizationId),organizationOnly:true},{action:"view",resource:ownerResource(actor.organizationId),organizationOnly:true}]);owner=nativeOwnerIdentityProjection({displayName:draft.target.input.displayName,email:draft.target.input.email??null,phone:draft.target.input.phone??null,preferredLocale:draft.target.input.preferredLocale});source={source:"CORE_OWNER_NEW_INPUT",inputFingerprint:commandFingerprint(draft.target.input)};}
 const reviewFingerprint=commandFingerprint({protocol,draft,source,policy:configured.snapshot,authorizationCap:captureAuthorizationCap(actor.authContext)});return{repository,current,configured,owner,source,reviewFingerprint};
}

type PropertyHead=Awaited<ReturnType<typeof nativeOnboardingPropertyHeads>>[number];
function propertyResource(organizationId:string,head?:PropertyHead,ownerId?:string){return{type:"property",organizationId,id:head?.id,propertyId:head?.id,ownerId:head?.ownership.some(row=>row.ownerId===ownerId)?ownerId:undefined,city:head?.cityId,region:head?.regionId,status:head?.status,occurredAt:head?.createdAt,dataClass:"operational"as const};}
function propertySnapshot(owner:NonNullable<Awaited<ReturnType<typeof nativeOnboardingOwnerWitness>>>,head:PropertyHead,initialConfiguration:Awaited<ReturnType<typeof configuredNativeOnboardingPropertyProfile>>["pin"]|null){return{source:"CORE_PROPERTY_IDENTITY",owner:sourceSnapshot(owner),property:{...head,createdAt:head.createdAt.toISOString(),updatedAt:head.updatedAt.toISOString(),archivedAt:head.archivedAt?.toISOString()??null},initialConfiguration};}
async function propertyDraftContext(actor:AccountActorContext,tx:TenantTransaction,draft:OnboardingPropertyDraft){
 const base=await sessionContext(actor,tx,draft.sessionId,"edit",true),repository=base.repository,current=base.row;
 if(current.id!==draft.previousRevisionId||!["OWNER","PROPERTY"].includes(current.step))throw new OnboardingConflictError();
 const configured=await settings(tx,actor.organizationId,await repository.clock());if(!configured.policy.property_modes?.includes(draft.target.mode))throw new OnboardingConfigurationError();
 await ownerRead(actor,tx,current.ownerId);const ownerBefore=await nativeOnboardingOwnerWitness(tx,actor.organizationId,current.ownerId),identity=await nativeOnboardingOwnerIdentity(tx,actor.organizationId,current.ownerId);if(!ownerBefore||!identity)throw new OnboardingAccessError();
 let property=null,source,creationConfiguration=null;
 if(draft.target.mode==="CREATE"){
  if(draft.target.input.ownerId!==current.ownerId)throw new OnboardingConflictError();
  await authority(actor,tx,[{action:"view",resource:propertyResource(actor.organizationId),organizationOnly:true},{action:"create",resource:propertyResource(actor.organizationId),organizationOnly:true}]);
  if(!configured.policy.property_creation_rule)throw new OnboardingConfigurationError();
  try{creationConfiguration=await configuredNativeOnboardingPropertyProfile(tx,actor.organizationId,configured.policy.property_creation_rule,await repository.clock());}catch(error){if(error instanceof z.ZodError||error instanceof Error&&error.message.startsWith("native_onboarding_"))throw new OnboardingConfigurationError();throw error;}
  source={source:"CORE_PROPERTY_NEW_INPUT",owner:sourceSnapshot(ownerBefore),inputFingerprint:commandFingerprint(draft.target.input),initialConfiguration:creationConfiguration.pin,initialProfileFingerprint:commandFingerprint(creationConfiguration.profile)};
 }else{
  const [head]=await nativeOnboardingPropertyHeads(tx,actor.organizationId,[draft.target.propertyId]);if(!head||!head.ownership.some(row=>row.ownerId===current.ownerId)||!["DRAFT","ONBOARDING"].includes(head.status))throw new OnboardingAccessError();
  await authority(actor,tx,[{action:"view",resource:propertyResource(actor.organizationId,head,current.ownerId)},{action:"edit",resource:propertyResource(actor.organizationId,head,current.ownerId)}]);
  const [row]=await nativeOnboardingPropertyRows(tx,actor.organizationId,[head.id]),[fresh]=await nativeOnboardingPropertyHeads(tx,actor.organizationId,[head.id]);if(!row||!fresh||commandFingerprint(head)!==commandFingerprint(fresh))throw new OnboardingConflictError();property=nativeOnboardingPropertyProjection(row);source=propertySnapshot(ownerBefore,fresh,null);
 }
 const ownerAfter=await nativeOnboardingOwnerWitness(tx,actor.organizationId,current.ownerId);if(!ownerAfter||commandFingerprint(sourceSnapshot(ownerBefore))!==commandFingerprint(sourceSnapshot(ownerAfter)))throw new OnboardingConflictError();
 const reviewFingerprint=commandFingerprint({protocol,draft,source,policy:configured.snapshot,authorizationCap:captureAuthorizationCap(actor.authContext)});
 return{repository,current,configured,owner:nativeOwnerIdentityProjection(identity),ownerWitness:ownerAfter,property,source,creationConfiguration,reviewFingerprint};
}

export async function reviewOnboardingPropertyStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){
 const ctx=actorContext(actor),draft=canonicalOnboardingPropertyDraft(raw);await spendRead(ctx,deps,draft.sessionId);
 return withTenant(deps.db,ctx.organizationId,async tx=>{const base=await propertyDraftContext(ctx,tx,draft);await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.step_reviewed",resourceType:"onboarding",resourceId:draft.sessionId,after:{sessionId:draft.sessionId,step:draft.step,reviewFingerprint:base.reviewFingerprint},requestId:deps.requestId??randomUUID(),occurredAt:await base.repository.clock()});const final=await propertyDraftContext(ctx,tx,draft);if(final.reviewFingerprint!==base.reviewFingerprint)throw new OnboardingConflictError();return onboardingPropertyReviewSchema.parse({draft,owner:final.owner,property:final.property,reviewFingerprint:final.reviewFingerprint});});
}

function operatingRuleSource(rule:Awaited<ReturnType<typeof nativeOnboardingOperatingRule>>){return rule?{scopes:rule.scopes,pin:rule.pin}:null;}
async function operatingDraftContext(actor:AccountActorContext,tx:TenantTransaction,draft:OnboardingOperatingDraft){
 const base=await sessionContext(actor,tx,draft.sessionId,"edit",true),repository=base.repository,current=base.row;
 if(current.id!==draft.previousRevisionId||!current.propertyId||current.propertyId!==draft.target.propertyId||!["PROPERTY","OPERATING_PROFILE"].includes(current.step))throw new OnboardingConflictError();
 const configured=await settings(tx,actor.organizationId,await repository.clock());if(!configured.policy.operating_profile_modes?.includes(draft.target.mode))throw new OnboardingConfigurationError();
 const ownerBefore=await ownerRead(actor,tx,current.ownerId),ownerWitness=await nativeOnboardingOwnerWitness(tx,actor.organizationId,current.ownerId);if(!ownerWitness||ownerBefore.id!==ownerWitness.id)throw new OnboardingAccessError();
 const[head]=await nativeOnboardingPropertyHeads(tx,actor.organizationId,[current.propertyId]);if(!head||!head.ownership.some(row=>row.ownerId===current.ownerId)||!["DRAFT","ONBOARDING"].includes(head.status))throw new OnboardingAccessError();
 const checks:CurrentAuthorityCheck[]=[{action:"view",resource:propertyResource(actor.organizationId,head,current.ownerId)},...draft.target.mode==="UPDATE"?[{action:"edit"as const,resource:propertyResource(actor.organizationId,head,current.ownerId)}]:[]];await authority(actor,tx,checks);
 const[row]=await nativeOnboardingPropertyRows(tx,actor.organizationId,[head.id]),identity=await nativeOnboardingOwnerIdentity(tx,actor.organizationId,current.ownerId);if(!row||!identity)throw new OnboardingAccessError();
 let previousOperatingProfile,operatingProfile,operatingRule;try{previousOperatingProfile=await nativeOnboardingOperatingProfile(tx,actor.organizationId,head.id);if(draft.target.mode==="LINK"){if(!previousOperatingProfile)throw new OnboardingConfigurationError();operatingProfile=previousOperatingProfile;}else operatingProfile=proposedNativeOperatingProfile(draft.target.input);operatingRule=await nativeOnboardingOperatingRule(tx,actor.organizationId,head.id,current.ownerId,operatingProfile,await repository.clock());}catch(error){if(error instanceof OnboardingConfigurationError)throw error;if(error instanceof z.ZodError||error instanceof Error&&error.message.startsWith("native_onboarding_"))throw new OnboardingConfigurationError();throw error;}
 const property=nativeOnboardingPropertyProjection(row),[fresh]=await nativeOnboardingPropertyHeads(tx,actor.organizationId,[head.id]),ownerAfter=await nativeOnboardingOwnerWitness(tx,actor.organizationId,current.ownerId);
 if(!fresh||!ownerAfter||commandFingerprint(head)!==commandFingerprint(fresh)||commandFingerprint(sourceSnapshot(ownerWitness))!==commandFingerprint(sourceSnapshot(ownerAfter)))throw new OnboardingConflictError();
 const source={source:"CORE_PROPERTY_OPERATING_PROFILE",property:propertySnapshot(ownerAfter,fresh,null),profileFingerprint:commandFingerprint(previousOperatingProfile),operatingRule:operatingRuleSource(operatingRule)},reviewFingerprint=commandFingerprint({protocol,draft,source,policy:configured.snapshot,authorizationCap:captureAuthorizationCap(actor.authContext)});
 return{repository,current,configured,owner:nativeOwnerIdentityProjection(identity),ownerWitness:ownerAfter,property,previousOperatingProfile,operatingProfile,operatingRule,source,reviewFingerprint};
}
export async function reviewOnboardingOperatingStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){
 const ctx=actorContext(actor),draft=canonicalOnboardingOperatingDraft(raw);await spendRead(ctx,deps,draft.sessionId);
 return withTenant(deps.db,ctx.organizationId,async tx=>{const base=await operatingDraftContext(ctx,tx,draft);await writeAuditEvent(tx,{organizationId:ctx.organizationId,actorId:ctx.actorId,action:"onboarding.step_reviewed",resourceType:"onboarding",resourceId:draft.sessionId,after:{sessionId:draft.sessionId,step:draft.step,reviewFingerprint:base.reviewFingerprint},requestId:deps.requestId??randomUUID(),occurredAt:await base.repository.clock()});const final=await operatingDraftContext(ctx,tx,draft);if(final.reviewFingerprint!==base.reviewFingerprint)throw new OnboardingConflictError();return onboardingOperatingReviewSchema.parse({draft,owner:final.owner,property:final.property,previousOperatingProfile:final.previousOperatingProfile,operatingProfile:final.operatingProfile,operatingRule:nativeOperatingRuleProjection(final.operatingRule?{...final.operatingRule.pin,value:final.operatingRule.value}:null),reviewFingerprint:final.reviewFingerprint});});
}

async function propertyRead(actor:AccountActorContext,tx:TenantTransaction,propertyId:string,ownerId:string,write=false,includeArchived=false){
 const [head]=await nativeOnboardingPropertyHeads(tx,actor.organizationId,[propertyId],includeArchived);if(!head)throw new OnboardingAccessError();
 await authority(actor,tx,[{action:"view",resource:propertyResource(actor.organizationId,head,ownerId)},...write?[{action:"edit"as const,resource:propertyResource(actor.organizationId,head,ownerId)}]:[]]);return head;
}
function retainedProperty(row:Row,env?:NodeJS.ProcessEnv){
 if(row.step!=="PROPERTY"||!row.propertyId)throw new OnboardingConflictError();
 const value=decryptOnboardingPropertyPayload(row.encryptedPayload,{...binding(row),propertyId:row.propertyId},env);
 if(value.command.reviewFingerprint!==row.reviewFingerprint||value.command.previousRevisionId!==row.previousId||value.command.target.mode!==row.mode)throw new OnboardingConfigurationError();return value;
}
function retainedOperating(row:Row,env?:NodeJS.ProcessEnv){
 if(row.step!=="OPERATING_PROFILE"||!row.propertyId)throw new OnboardingConflictError();
 const value=decryptOnboardingOperatingPayload(row.encryptedPayload,{...binding(row),propertyId:row.propertyId},env);
 if(value.command.reviewFingerprint!==row.reviewFingerprint||value.command.previousRevisionId!==row.previousId||value.command.target.mode!==row.mode)throw new OnboardingConfigurationError();return value;
}
async function recoverPropertyExisting(actor:AccountActorContext,tx:TenantTransaction,row:Row,deps:OnboardingDependencies,command?:OnboardingPropertyCommand|OnboardingOperatingCommand|OnboardingCommand){
 if(row.createdBy!==actor.actorId)throw new OnboardingAccessError();if(!["PROPERTY","OPERATING_PROFILE"].includes(row.step)||!row.propertyId)throw new OnboardingConflictError();
 const base=await sessionContext(actor,tx,row.sessionId);await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId,row)}]);await ownerRead(actor,tx,row.ownerId,false,true);await propertyRead(actor,tx,row.propertyId,row.ownerId,false,true);
 if(command&&!timingSafeEqual(Buffer.from(commandFingerprint((row.step==="PROPERTY"?retainedProperty(row,deps.env):retainedOperating(row,deps.env)).command),"hex"),Buffer.from(commandFingerprint(command),"hex")))throw new OnboardingConflictError();
 await writeAuditEvent(tx,{organizationId:actor.organizationId,actorId:actor.actorId,action:"onboarding.step_recovered",resourceType:"onboarding",resourceId:row.sessionId,after:{sessionId:row.sessionId,revisionId:row.id,commandHash:row.commandHash},requestId:deps.requestId??randomUUID(),occurredAt:await base.repository.clock()});
 await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId,row)},{action:"view",resource:resource(actor.organizationId,base.row)}]);await ownerRead(actor,tx,row.ownerId,false,true);await propertyRead(actor,tx,row.propertyId,row.ownerId,false,true);return receipt(row,true);
}
