export async function recoverOnboardingPropertyStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return recoverNativePropertyStep(actor,raw,deps,"PROPERTY");}
export async function recoverOnboardingOperatingStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return recoverNativePropertyStep(actor,raw,deps,"OPERATING_PROFILE");}
async function recoverNativePropertyStep(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies,expectedStep:"PROPERTY"|"OPERATING_PROFILE"){
 const ctx=actorContext(actor),input=recoverInput.parse(raw),existing=await withTenant(deps.db,ctx.organizationId,async tx=>{const row=await new OnboardingRepository(tx,ctx.organizationId).byNonce(input.idempotencyKey);if(row){if(row.createdBy!==ctx.actorId||input.sessionId&&row.sessionId!==input.sessionId)throw new OnboardingAccessError();if(row.step!==expectedStep||!row.propertyId)throw new OnboardingConflictError();await sessionContext(ctx,tx,row.sessionId);await propertyRead(ctx,tx,row.propertyId,row.ownerId,false,true);return row;}if(input.sessionId)await sessionContext(ctx,tx,input.sessionId);else await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);return null;});
 await spendRead(ctx,deps,existing?.sessionId??input.sessionId);return withTenant(deps.db,ctx.organizationId,async tx=>{const row=await new OnboardingRepository(tx,ctx.organizationId).byNonce(input.idempotencyKey);if(!row){if(input.sessionId)await sessionContext(ctx,tx,input.sessionId);else await authority(ctx,tx,[{action:"view",resource:resource(ctx.organizationId),organizationOnly:true}]);return{recorded:false,revision:null};}if(input.sessionId&&row.sessionId!==input.sessionId)throw new OnboardingAccessError();return{recorded:true,revision:await recoverPropertyExisting(ctx,tx,row,deps)};});
}
export async function readOnboardingPropertySession(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return onboardingPropertyReadSchema.parse(await readRecordInternal(actor,raw,deps,"PROPERTY"));}
export async function readOnboardingOperatingSession(actor:AccountActorContext,raw:unknown,deps:OnboardingDependencies){return onboardingOperatingReadSchema.parse(await readRecordInternal(actor,raw,deps,"OPERATING_PROFILE"));}


async function recoverExisting(actor:AccountActorContext,tx:TenantTransaction,row:Row,deps:OnboardingDependencies,command?:OnboardingCommand|OnboardingManagementAgreementCommand|OnboardingTeamCommand|OnboardingBookingChannelsCommand|OnboardingInventoryCommand|OnboardingServicesCommand|OnboardingWorkflowsCommand|OnboardingConfigurationCommand){
 if(row.step==="REVIEW"){if(command&&command.step!=="REVIEW")throw new OnboardingConflictError();return recoverConfigurationExisting(actor,tx,row,deps,command);}
 if(command?.step==="REVIEW")throw new OnboardingConflictError();
 if(row.step==="WORKFLOWS"){if(command&&command.step!=="WORKFLOWS")throw new OnboardingConflictError();return recoverWorkflowsExisting(actor,tx,row,deps,command);}
 if(row.step==="SERVICES"){if(command&&command.step!=="SERVICES")throw new OnboardingConflictError();return recoverServicesExisting(actor,tx,row,deps,command);}
 if(row.step==="INVENTORY"){if(command&&command.step!=="INVENTORY")throw new OnboardingConflictError();return recoverInventoryExisting(actor,tx,row,deps,command);}
 if(command?.step==="INVENTORY"||command?.step==="SERVICES"||command?.step==="WORKFLOWS")throw new OnboardingConflictError();
 if(row.step==="TEAM"){if(command&&command.step!=="TEAM")throw new OnboardingConflictError();return recoverTeamExisting(actor,tx,row,deps,command);}
 if(row.step==="BOOKING_CHANNELS"){if(command&&command.step!=="BOOKING_CHANNELS")throw new OnboardingConflictError();return recoverBookingChannelsExisting(actor,tx,row,deps,command);}
 if(command?.step==="TEAM"||command?.step==="BOOKING_CHANNELS")throw new OnboardingConflictError();
 if(row.step==="MANAGEMENT_AGREEMENT"){if(command&&command.step!=="MANAGEMENT_AGREEMENT")throw new OnboardingConflictError();return recoverManagementExisting(actor,tx,row,deps,command);}
 if(command?.step==="MANAGEMENT_AGREEMENT")throw new OnboardingConflictError();
 if(row.step==="PROPERTY"||row.step==="OPERATING_PROFILE")return recoverPropertyExisting(actor,tx,row,deps,command);
 if(row.createdBy!==actor.actorId)throw new OnboardingAccessError();const base=await sessionContext(actor,tx,row.sessionId);await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId,row)}]);await ownerRead(actor,tx,row.ownerId,false,true);if(command&&!timingSafeEqual(Buffer.from(commandFingerprint(retained(row,deps.env).command),"hex"),Buffer.from(commandFingerprint(command),"hex")))throw new OnboardingConflictError();await writeAuditEvent(tx,{organizationId:actor.organizationId,actorId:actor.actorId,action:"onboarding.step_recovered",resourceType:"onboarding",resourceId:row.sessionId,after:{sessionId:row.sessionId,revisionId:row.id,commandHash:row.commandHash},requestId:deps.requestId??randomUUID(),occurredAt:await base.repository.clock()});await authority(actor,tx,[{action:"view",resource:resource(actor.organizationId,row)},{action:"view",resource:resource(actor.organizationId,base.row)}]);await ownerRead(actor,tx,row.ownerId,false,true);return receipt(row,true);
}

async function operatingOptions(actor:AccountActorContext,tx:TenantTransaction,row:Row){
 if(!row.propertyId||!["PROPERTY","OPERATING_PROFILE"].includes(row.step))return null;
 try{
  const repository=new OnboardingRepository(tx,actor.organizationId),configured=await settings(tx,actor.organizationId,await repository.clock());if(!configured.policy.operating_profile_modes?.length)return null;
  const current=await sessionContext(actor,tx,row.sessionId,"edit",true);if(current.row.id!==row.id)throw new OnboardingConflictError();
  await ownerRead(actor,tx,row.ownerId);const owner=await nativeOnboardingOwnerWitness(tx,actor.organizationId,row.ownerId),head=await propertyRead(actor,tx,row.propertyId,row.ownerId);
  if(!owner||!head.ownership.some(value=>value.ownerId===row.ownerId)||!["DRAFT","ONBOARDING"].includes(head.status))return null;
  const profile=await nativeOnboardingOperatingProfile(tx,actor.organizationId,row.propertyId),modes:("LINK"|"UPDATE")[]=[];let operatingRule:Awaited<ReturnType<typeof nativeOnboardingOperatingRule>>=null;
  for(const mode of configured.policy.operating_profile_modes){
   if(mode==="LINK"){
    if(!profile)continue;try{operatingRule=await nativeOnboardingOperatingRule(tx,actor.organizationId,row.propertyId,row.ownerId,profile,await repository.clock());modes.push(mode);}catch(error){if(!(error instanceof z.ZodError)&&!(error instanceof Error&&error.message.startsWith("native_onboarding_")))throw error;}
   }else{try{await authority(actor,tx,[{action:"edit",resource:propertyResource(actor.organizationId,head,row.ownerId)}]);modes.push(mode);}catch(error){if(!(error instanceof OnboardingAccessError))throw error;}}
  }
  if(!modes.length)return null;const[physical]=await nativeOnboardingPropertyRows(tx,actor.organizationId,[row.propertyId]);if(!physical)throw new OnboardingAccessError();
  const data=onboardingOperatingOptionsSchema.parse({revisionId:row.id,propertyId:row.propertyId,propertyName:physical.name,modes,profile});
  return{data,fingerprint:commandFingerprint({revisionId:row.id,source:propertySnapshot(owner,head,null),profile,operatingRule,policy:configured.snapshot,authorizationCap:captureAuthorizationCap(actor.authContext)})};
 }catch(error){if(error instanceof OnboardingAccessError||error instanceof OnboardingConfigurationError||error instanceof z.ZodError)return null;throw error;}
}
