   const page=await nativeOnboardingManagementAgreementChoices(tx,actor.organizationId,row.propertyId,"",undefined,await repository.clock()),ids=page.slice(0,50).map(value=>value.id);choices=await nativeOnboardingManagementAgreementHeads(tx,actor.organizationId,ids);rules=await nativeOnboardingManagementAgreementRuleHeadsMany(tx,actor.organizationId,ids);
